<script setup>
import { computed, onMounted, reactive, ref, watch } from 'vue'
import api from '../services/api'
const branches=ref([]), stocks=ref([]), selectedBranch=ref(''), filter=ref('all'), showAdjust=ref(false), showTransfer=ref(false), notice=ref(''), error=ref('')
const adjust=reactive({product_id:'',quantity:'',reason:'',notes:''}), transfer=reactive({product_id:'',to_branch_id:'',quantity:'',notes:''})
const loadBranches=async()=>{const {data}=await api.get('/businesses');const business=data.data[0];if(!business)return;const response=await api.get(`/businesses/${business.id}/branches`);branches.value=response.data.data;if(!selectedBranch.value&&branches.value.length)selectedBranch.value=branches.value[0].id}
const loadStocks=async()=>{if(!selectedBranch.value)return;const {data}=await api.get('/inventory/stocks',{params:{branch_id:selectedBranch.value}});stocks.value=data.data}
onMounted(async()=>{await loadBranches();await loadStocks()});watch(selectedBranch,loadStocks)
const visible=computed(()=>filter.value==='all'?stocks.value:filter.value==='low'?stocks.value.filter(s=>Number(s.quantity)>0&&Number(s.quantity)<=Number(s.reorder_level)):stocks.value.filter(s=>Number(s.quantity)===0))
const submitAdjustment=async()=>{error.value='';try{await api.post('/inventory/adjustments',{...adjust,branch_id:selectedBranch.value,quantity:Number(adjust.quantity)});Object.assign(adjust,{product_id:'',quantity:'',reason:'',notes:''});showAdjust.value=false;notice.value='স্টক সমন্বয় সফলভাবে সংরক্ষিত হয়েছে।';loadStocks()}catch(e){error.value=e.response?.data?.message||'স্টক সমন্বয় করা যায়নি।'}}
const submitTransfer=async()=>{error.value='';try{await api.post('/inventory/transfers',{...transfer,from_branch_id:selectedBranch.value,quantity:Number(transfer.quantity)});Object.assign(transfer,{product_id:'',to_branch_id:'',quantity:'',notes:''});showTransfer.value=false;notice.value='স্টক ট্রান্সফার সফল হয়েছে।';loadStocks()}catch(e){error.value=e.response?.data?.message||'স্টক ট্রান্সফার করা যায়নি।'}}
const setReorder=async(stock)=>{const value=window.prompt(`পুনঃঅর্ডার স্তর: ${stock.product.name}`,stock.reorder_level);if(value===null)return;await api.put(`/inventory/stocks/${stock.id}`,{reorder_level:Number(value)});notice.value='পুনঃঅর্ডার স্তর আপডেট হয়েছে।';loadStocks()}
</script>
<template><section><div class="page-heading inline"><div><p class="eyebrow">INVENTORY CONTROL</p><h2>স্টক ব্যবস্থাপনা</h2><p>শাখাভিত্তিক স্টক, পুনঃঅর্ডার স্তর, সমন্বয় এবং ট্রান্সফার নিয়ন্ত্রণ করুন।</p></div><div class="button-row"><button class="secondary" @click="showTransfer=true">⇄ স্টক ট্রান্সফার</button><button class="primary" @click="showAdjust=true">± স্টক সমন্বয়</button></div></div><div class="toolbar"><label>শাখা<select v-model="selectedBranch"><option v-for="branch in branches" :value="branch.id">{{branch.name}}</option></select></label><div class="tabs"><button :class="{active:filter==='all'}" @click="filter='all'">সব স্টক</button><button :class="{active:filter==='low'}" @click="filter='low'">কম স্টক</button><button :class="{active:filter==='out'}" @click="filter='out'">স্টক শেষ</button></div></div><p v-if="notice" class="success notice">✓ {{notice}}</p><div v-if="showAdjust" class="page-card compact"><form class="form-grid" @submit.prevent="submitAdjustment"><label>পণ্য<select v-model="adjust.product_id" required><option value="">নির্বাচন করুন</option><option v-for="stock in stocks" :value="stock.product_id">{{stock.product.name}} (বর্তমান: {{stock.quantity}})</option></select></label><label>পরিমাণ<input v-model.number="adjust.quantity" type="number" step="0.001" placeholder="+10 অথবা -2" required /></label><label>কারণ<input v-model="adjust.reason" placeholder="যেমন: নতুন মাল এসেছে" required /></label><label>নোট<input v-model="adjust.notes" /></label><p v-if="error" class="error">{{error}}</p><div class="full-width form-actions"><button type="button" class="secondary" @click="showAdjust=false">বাতিল</button><button class="primary">সমন্বয় সংরক্ষণ করুন</button></div></form></div><div v-if="showTransfer" class="page-card compact"><form class="form-grid" @submit.prevent="submitTransfer"><label>পণ্য<select v-model="transfer.product_id" required><option value="">নির্বাচন করুন</option><option v-for="stock in stocks" :value="stock.product_id">{{stock.product.name}} (বর্তমান: {{stock.quantity}})</option></select></label><label>গন্তব্য শাখা<select v-model="transfer.to_branch_id" required><option value="">নির্বাচন করুন</option><option v-for="branch in branches.filter(b=>b.id!==selectedBranch)" :value="branch.id">{{branch.name}}</option></select></label><label>পরিমাণ<input v-model.number="transfer.quantity" type="number" min="0.001" step="0.001" required /></label><label>নোট<input v-model="transfer.notes" /></label><p v-if="error" class="error">{{error}}</p><div class="full-width form-actions"><button type="button" class="secondary" @click="showTransfer=false">বাতিল</button><button class="primary">ট্রান্সফার সম্পন্ন করুন</button></div></form></div><div class="table-card"><table><thead><tr><th>পণ্য</th><th>SKU</th><th>বর্তমান স্টক</th><th>পুনঃঅর্ডার স্তর</th><th>স্ট্যাটাস</th><th></th></tr></thead><tbody><tr v-for="stock in visible" :key="stock.id"><td><strong>{{stock.product.name}}</strong><small>{{stock.product.unit?.name||'—'}} · {{stock.product.category?.name||'—'}}</small></td><td>{{stock.product.sku}}</td><td><strong :class="Number(stock.quantity)<=Number(stock.reorder_level)?'due':''">{{stock.quantity}}</strong></td><td>{{stock.reorder_level}}</td><td><span v-if="Number(stock.quantity)===0" class="status danger">● স্টক শেষ</span><span v-else-if="Number(stock.quantity)<=Number(stock.reorder_level)" class="status warn">● কম স্টক</span><span v-else class="status active">● পর্যাপ্ত</span></td><td><button class="secondary tiny" @click="setReorder(stock)">পুনঃঅর্ডার</button></td></tr><tr v-if="!visible.length"><td colspan="6" class="empty">এই ফিল্টারে কোনো স্টক রেকর্ড নেই। পণ্য যোগ করে স্টক সমন্বয় করুন।</td></tr></tbody></table></div></section></template>
